private function resolveSubjectId(string $frontendSubject): int
{
    $subjectMap = [
        'Chinese' => '國文',
        'English' => '英文',
        'Math' => '數學',
        'Physics' => '物理',
        'Chemistry' => '化學',
        'Science' => '理化',
        'Biology' => '生物',
        'Social' => '社會',
    ];
    $subjectName = $subjectMap[$frontendSubject] ?? $frontendSubject;

    return (int) (
        DB::table('Subject')->where('Subject_Name', 'like', '%' . $subjectName . '%')->value('id')
        ?? DB::table('BaseData')->where('Name', '課程')->where('Val', 'like', '%' . $subjectName . '%')->value('id')
        ?? 1
    );
}

private function resolveSubjectName(int $subjectId, string $fallback): string
{
    $name = DB::table('Subject')->where('id', $subjectId)->value('Subject_Name')
        ?? DB::table('BaseData')->where('Name', '課程')->where('id', $subjectId)->value('Val');
    return (string) ($name ?: $fallback);
}

private static function resolveEquivalentSubjectIds(int $subjectId): array
{
    if ($subjectId <= 0 || !Schema::hasTable('Subject')) {
        return [$subjectId];
    }

    $rows = DB::table('Subject')->get(['id', 'Subject_Name']);
    if ($rows->isEmpty()) {
        return [$subjectId];
    }

    $targetRow = $rows->firstWhere('id', $subjectId);
    $targetName = self::normalizeSubjectName((string) ($targetRow->Subject_Name ?? ''));
    if ($targetName === '') {
        return [$subjectId];
    }

    $ids = $rows
        ->filter(fn ($row) => self::normalizeSubjectName((string) ($row->Subject_Name ?? '')) === $targetName)
        ->pluck('id')
        ->map(fn ($id) => (int) $id)
        ->filter(fn ($id) => $id > 0)
        ->values()
        ->all();

    if (!in_array($subjectId, $ids, true)) {
        $ids[] = $subjectId;
    }

    return array_values(array_unique($ids));
}

